func SetConfigItem(c types.Config) error {
	// safety checks
	canSet, err := canSetConfig(c.Key)
	if !canSet {
		return err
	}

	return setConfigItem(c)
}

func SetConfigItemWithoutValidation(c types.Config) error {
	return setConfigItem(c)
}

func setConfigItem(c types.Config) error {
	args := []string{
		"config",
		"set",
		GetConstConfigTable()[c.Key].Who,
		c.Key,
		c.Value,
		"-f",
		"json-pretty",
	}

	_, err := processExec.RunCommand("ceph", args...)
	if err != nil {
		return err
	}

	return nil
}

